const D = { density:.55, scale:1, energy:.65, speed:1, hue:32, tilt:.6, doppler:.7, x:.5, y:.5, style:'spacetime', act:'orbit', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const W = width, H = height, u = Math.min(W, H), TAU = Math.PI * 2;
const clp = (v,a,b) => Math.max(a, Math.min(b, v));
const st = P.style;
const wire=(st==='wire'), ink=(st==='ink'), irid=(st==='iridescent'), thermal=(st==='thermal');
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const intn = (K.intensity!=null?K.intensity:0.6);

// ---- seed-dependent particle ring family ----
const MAXN = 200;
if (S.seedUsed !== P.seed){
  S.seedUsed = P.seed;
  S.p = [];
  for (let i=0;i<MAXN;i++) S.p.push({ rf: Math.pow(fr(i*2+1),0.75), ph: fr(i*2+2)*TAU, jz: fr(i*3+5) });
}

// ---- cached deep-space + starfield (size+seed+style keyed) ----
const bgKey = W+'x'+H+'_'+P.seed+'_'+st;
if (!S.bg || S.bgKey!==bgKey){
  if (S.bg && S.bg.remove) S.bg.remove();
  S.bg = createGraphics(W,H);
  const g=S.bg; g.colorMode(g.HSB,360,100,100,100); g.noStroke();
  const cx=W/2, cy=H/2, mx=Math.max(W,H)*0.8, steps=64;
  for(let s=steps;s>=0;s--){
    const rr=mx*s/steps, f=s/steps;
    if(ink) g.fill(38,7-f*3,88-f*7,100);
    else if(wire) g.fill(206,45+f*25,10-f*5,100);
    else if(irid) g.fill(250,42+f*25,11-f*6,100);
    else if(thermal) g.fill(250,40+f*20,9-f*5,100);
    else g.fill(230,52+f*22,11-f*6,100);
    g.ellipse(cx,cy,rr*2,rr*2);
  }
  const nst=Math.floor((W*H)/3600);
  for(let i=0;i<nst;i++){
    const sx=fr(i*2+700)*W, sy=fr(i*2+701)*H, b=fr(i+1100);
    if(ink){ g.fill(35,15,44,24+b*34); g.ellipse(sx,sy,0.9+b*0.9,0.9+b*0.9); }
    else { const d=0.6+b*1.9; g.fill(b>0.9?42:208, b>0.9?24:13, 92, 22+b*72); g.ellipse(sx,sy,d,d); }
  }
  S.bgKey=bgKey;
}
image(S.bg,0,0);

// ---- geometry ----
const cx=P.x*W, cy=P.y*H;
const shadowR = u*0.115*clp(P.scale,0.4,2);
const innerR = shadowR*1.32;
const outerR = u*0.42*clp(P.scale,0.4,2);
// real-time tilt breathing: displaces the whole disk band vertically each frame,
// 0.34 rad/s -> ~2.7 rad over 8s, never re-phases at the gate.
const sqBase = 0.16 + (1-clp(P.tilt,0,1))*0.42;
const squash = sqBase*(0.72 + 0.34*Math.sin(K.t*0.34 + 0.6));
const glow = 0.4 + clp(P.energy,0,1)*0.6 + A.rms*0.8 + 0.1*Math.sin(K.t*0.6);
const dop = clp(P.doppler,0,1);
const nP = Math.max(24, Math.round(MAXN*(0.22+clp(P.density,0,1)*0.78)));
const spd = P.act==='flare' ? P.speed*(0.55+intn*1.0) : (P.act==='calm'? P.speed*0.55 : P.speed);
const kick = K.pulse*0.5 + A.bass*0.8;

push();
translate(cx,cy);
rotate(0.10*Math.sin(K.t*0.08));   // slow real-time precession

// ---- disk particles ----
if(!ink) blendMode(ADD); else blendMode(BLEND);
noStroke();
for(let i=0;i<nP;i++){
  const p=S.p[i];
  const rf=p.rf;
  const r=innerR + rf*(outerR-innerR);
  const w=0.9*Math.pow(innerR/r,1.5);
  const ang=p.ph + K.t*spd*w;
  const c=Math.cos(ang), s=Math.sin(ang);
  const px=c*r, py=s*r*squash;
  const beam = 1 + dop*0.9*(-c);
  const tHot = 1-rf;
  let hue=(P.hue+24-tHot*28-(c>0?dop*20:-dop*8)+360)%360;
  if(thermal) hue=(26-tHot*26+(c<0?18:0)+360)%360;
  if(irid) hue=(P.hue+rf*160+K.t*10+(c<0?40:0))%360;
  if(wire) hue=(196+(c<0?-18:20))%360;
  const bright=Math.min(100,(wire?46:(46+tHot*40))+glow*28+kick*10*(1-rf))*beam*(0.75+p.jz*0.4);
  const alpha=(wire?24:(ink?32:20+tHot*24))*beam;
  const sz=(1.6+tHot*2.6+p.jz*1.4)*clp(P.scale,0.4,2);
  const eh=Math.max(0.6,squash*2.6);
  if(wire){ stroke(hue,55,82,alpha*1.4); strokeWeight(1.5);
    const a2=ang+0.2; line(px,py,Math.cos(a2)*r,Math.sin(a2)*r*squash); noStroke(); }
  else if(ink){ fill(hue,24,20+tHot*10,alpha); ellipse(px,py,sz,sz); }
  else { fill(hue,thermal?92:(72-tHot*30),bright,alpha); ellipse(px,py,sz*1.6,sz*eh); }
}

// ---- BRIGHT ORBITING HOTSPOTS (dominant motion floor) ----
// Large soft blobs travel around the disk at K.t rate -> big grayscale mass
// moves frame-to-frame and materially over the 8s gate. Symmetry broken.
if(!ink) blendMode(ADD); else blendMode(BLEND);
const nHot = 4;
for(let i=0;i<nHot;i++){
  const rf = 0.18 + fr(i*7+31)*0.5;
  const r = innerR + rf*(outerR-innerR);
  const w = 0.9*Math.pow(innerR/r,1.5);
  // incommensurate real-time travel rates so at least one is always displaced
  const rate = 0.30 + i*0.13;
  const ang = fr(i*7+32)*TAU + K.t*spd*rate + K.t*0.14;
  const c=Math.cos(ang), s=Math.sin(ang);
  const px=c*r, py=s*r*squash;
  const beam = 1 + dop*0.85*(-c);
  const tHot = 1-rf;
  let hue=(P.hue+20-tHot*24-(c>0?dop*18:-dop*6)+360)%360;
  if(thermal) hue=(30-tHot*24+(c<0?16:0)+360)%360;
  if(irid) hue=(P.hue+rf*150+K.t*14+(c<0?40:0))%360;
  if(wire) hue=(198+(c<0?-16:22))%360;
  const bright=Math.min(100,(wire?66:60+tHot*30)+glow*24+kick*10);
  const rad=(outerR*(ink?0.40:0.34)+fr(i*7+34)*outerR*0.12);
  // layered translucent stack = soft glow (no full-canvas blur)
  const eh=Math.max(0.6,squash*2.6);
  for(let L=0;L<3;L++){
    const f=1-L*0.34;
    const al=(wire?18:(ink?24:15))*beam*(1-L*0.2);
    if(wire){ fill(hue,44,88,al); ellipse(px,py,rad*f*1.4,rad*f*eh);           // glowing node mass
      stroke(hue,50,92,al*1.1); strokeWeight(2.2); noFill(); ellipse(px,py,rad*f*1.5,rad*f*eh); noStroke(); }
    else if(ink){ fill(hue,28,16,al); ellipse(px,py,rad*f*1.6,rad*f*eh); }   // dark sumi wash
    else { fill(hue,thermal?90:(60-tHot*20),bright,al); ellipse(px,py,rad*f*1.6,rad*f*eh); }
  }
}

// ---- INFALLING BLOBS (seeded, K.t-driven spawn/despawn spiral) ----
// Each blob has a fixed birth-time bucket; it lives ~lifeSec then respawns.
// Continuous appear/disappear + inward spiral = ongoing change, all from K.t.
if(!ink) blendMode(ADD); else blendMode(BLEND);
const nBlob = 10;
const lifeSec = 4.2;
for(let i=0;i<nBlob;i++){
  const t0 = fr(i*11+3)*lifeSec;               // birth offset within cycle
  const cyc = (K.t*spd + t0)/lifeSec;
  const life = cyc - Math.floor(cyc);           // 0..1 progress this fall
  const gen = Math.floor(cyc);                  // which incarnation (reseeds params)
  const gh = fr(i*11 + gen*97 + 5);
  const a0 = gh*TAU;
  const rr = outerR*(0.98) - life*(outerR-innerR*1.02);   // spiral inward
  const spin = a0 + life*(3.2 + gh*2.4);        // wind as it falls
  const c=Math.cos(spin), s=Math.sin(spin);
  const px=c*rr, py=s*rr*squash;
  const fade = Math.sin(life*Math.PI);          // fade in/out
  if(fade<=0.02) continue;
  const tHot=1-rr/outerR;
  let hue=(P.hue+34+gh*30)%360;
  if(thermal) hue=(44-tHot*30+360)%360;
  if(irid) hue=(P.hue+rr*0.5+gen*40)%360;
  if(wire) hue=(200+gh*30)%360;
  const bright=Math.min(100,(wire?70:64+tHot*26)+glow*20);
  const rad=(outerR*(ink?0.13:0.09)+gh*outerR*0.05)*(0.6+fade*0.8);
  const eh=Math.max(0.6,squash*2.6);
  if(wire){ stroke(hue,50,86,42*fade); strokeWeight(2.2); noFill(); ellipse(px,py,rad*2,rad*2*eh*0.9); noStroke(); }
  else if(ink){ fill(hue,28,15,46*fade); ellipse(px,py,rad*2,rad*2*Math.max(0.5,eh*0.9)); }   // dark falling ink
  else { fill(hue,thermal?90:(58-tHot*18),bright,22*fade); ellipse(px,py,rad*2,rad*2*Math.max(0.5,eh*0.9)); }
}
blendMode(BLEND);

// ---- event-horizon shadow (occludes the mid band) ----
noStroke();
if(ink){ fill(38,6,84,100); ellipse(0,0,shadowR*2.04,shadowR*2.04); fill(38,14,12,100); ellipse(0,0,shadowR*2,shadowR*2); }
else { fill(0,0,0,100); ellipse(0,0,shadowR*2,shadowR*2); }

// ---- lensed photon ring / Einstein halo (arcs over top & bottom) ----
blendMode(ink?BLEND:ADD);
const ringR=shadowR*1.06, seg=96;
const flick = 0.8 + 0.2*Math.sin(K.t*3.1);     // subtle real-time ring flicker
for(let i=0;i<seg;i++){
  const a=i/seg*TAU, c=Math.cos(a), s=Math.sin(a);
  const beam=1 + dop*0.85*(-c);
  const hue= wire?196 : thermal?(30+(c<0?16:0)) : irid?((P.hue+K.t*12+(c<0?40:0))%360) : ((P.hue+18-(c>0?dop*18:-dop*6)+360)%360);
  const br=Math.min(100,(wire?70:66)*beam*flick + glow*22 + kick*10);
  const al=(ink?52:30)*beam;
  noStroke(); fill(hue, wire?45:(ink?20:58), br, al);
  const ps=(wire?1.6:2.6)+kick*1.6;
  ellipse(c*ringR, s*ringR, ps, ps);
}
blendMode(BLEND);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
